# Send action response with demo request
action_response = {"action": "request_demos"}
print(action_response)

import json

# Load demo pairs
with open('/home/ubuntu/runs/paper/qwen-hpl0-u1-turns/play/users/u000/system/state/workspace/tasks/task-29a29a25f46.json') as f:
    demos = json.load(f)

print("Demo pairs:")
for i, demo in enumerate(demos):
    print(f"\n=== Demo {i+1} ===")
    print(f"Input shape: {len(demo['input'])}x{len(demo['input'][0])}")
    print(f"Output shape: {len(demo['output'])}x{len(demo['output'][0])}")

    print("\nInput:")
    for r in range(min(10, len(demo['input']))):
        print(f"  Row {r}: {demo['input'][r]}")
    if len(demo['input']) > 10:
        print(f"  ...")

    print("\nOutput:")
    for r in range(min(10, len(demo['output']))):
        print(f"  Row {r}: {demo['output'][r]}")
    if len(demo['output']) > 10:
        print(f"  ...")

# Full numeric analysis
print("\n\n=== FULL NUMERIC ANALYSIS ===\n")

for demo in demos:
    inp = demo['input']
    out = demo['output']

    print(f"Demo: input {len(inp)}x{len(inp[0])} -> output {len(out)}x{len(out[0])}")

    # Find unique values
    in_vals = {}
    for r, row in enumerate(inp):
        for c, v in enumerate(row):
            if v not in in_vals:
                in_vals[v] = []
            in_vals[v].append((r,c))

    out_vals = {}
    for r, row in enumerate(out):
        for c, v in enumerate(row):
            if v not in out_vals:
                out_vals[v] = []
            out_vals[v].append((r,c))

    print(f"\n  Input unique values: {in_vals}")
    print(f"  Output unique values: {out_vals}")

    # Find axes/separator lines
    print("\n  Looking for axes:")
    # Check each column for being uniform
    uniform_cols_in = set()
    uniform_cols_out = set()
    for c in range(len(inp[0])):
        col_vals = set(inp[r][c] for r in range(len(inp)))
        if len(col_vals) == 1:
            uniform_cols_in.add(c)
    for c in range(len(out[0])):
        col_vals = set(out[r][c] for r in range(len(out)))
        if len(col_vals) == 1:
            uniform_cols_out.add(c)
    print(f"    Input uniform columns: {uniform_cols_in}")
    print(f"    Output uniform columns: {uniform_cols_out}")

    # Check rows
    uniform_rows_in = set()
    uniform_rows_out = set()
    for r in range(len(inp)):
        row_vals = set(inp[r])
        if len(row_vals) == 1:
            uniform_rows_in.add(r)
    for r in range(len(out)):
        row_vals = set(out[r])
        if len(row_vals) == 1:
            uniform_rows_out.add(r)
    print(f"    Input uniform rows: {uniform_rows_in}")
    print(f"    Output uniform rows: {uniform_rows_out}")

